append(
            statements,
            setOriginalNode(
                setTextRange(
                    factory.createVariableStatement(
                        /*modifiers*/ undefined,
                        factory.createVariableDeclarationList(
                            [
                                factory.createVariableDeclaration(
                                    factory.cloneNode(node.name),
                                    /*exclamationToken*/ undefined,
                                    /*type*/ undefined,
                                    createRequireCall(node),
                                ),
                            ],
                            /*flags*/ languageVersion >= ScriptTarget.ES2015 ? NodeFlags.Const : NodeFlags.None,
                        ),
                    ),
                    node,
                ),
                node,
            ),
        )

append(
                statements,
                factory.createExportDeclaration(
                    /*modifiers*/ undefined,
                    node.isTypeOnly,
                    factory.createNamedExports([factory.createExportSpecifier(/*isTypeOnly*/ false, /*propertyName*/ undefined, idText(node.name))]),
                ),
            )

append(
                    statements,
                    setOriginalNode(
                        setTextRange(
                            factory.createVariableStatement(
                                /*modifiers*/ undefined,
                                factory.createVariableDeclarationList(
                                    variables,
                                    languageVersion >= ScriptTarget.ES2015 ? NodeFlags.Const : NodeFlags.None,
                                ),
                            ),
                            /*location*/ node,
                        ),
                        /*original*/ node,
                    ),
                )

append(
                statements,
                factory.createVariableStatement(
                    /*modifiers*/ undefined,
                    factory.createVariableDeclarationList(
                        [
                            setOriginalNode(
                                setTextRange(
                                    factory.createVariableDeclaration(
                                        factory.cloneNode(namespaceDeclaration.name),
                                        /*exclamationToken*/ undefined,
                                        /*type*/ undefined,
                                        factory.getGeneratedNameForNode(node),
                                    ),
                                    /*location*/ node,
                                ),
                                /*original*/ node,
                            ),
                        ],
                        languageVersion >= ScriptTarget.ES2015 ? NodeFlags.Const : NodeFlags.None,
                    ),
                ),
            )

append(
                    statements,
                    setOriginalNode(
                        setTextRange(
                            factory.createExpressionStatement(
                                createExportExpression(
                                    node.name,
                                    createRequireCall(node),
                                ),
                            ),
                            node,
                        ),
                        node,
                    ),
                )

append(
                    statements,
                    setOriginalNode(
                        setTextRange(
                            factory.createVariableStatement(
                                /*modifiers*/ undefined,
                                factory.createVariableDeclarationList(
                                    [
                                        factory.createVariableDeclaration(
                                            factory.cloneNode(node.name),
                                            /*exclamationToken*/ undefined,
                                            /*type*/ undefined,
                                            createRequireCall(node),
                                        ),
                                    ],
                                    /*flags*/ languageVersion >= ScriptTarget.ES2015 ? NodeFlags.Const : NodeFlags.None,
                                ),
                            ),
                            node,
                        ),
                        node,
                    ),
                )

append(
                    statements,
                    setOriginalNode(
                        setTextRange(
                            factory.createExpressionStatement(
                                createExportExpression(factory.getExportName(node), factory.getLocalName(node)),
                            ),
                            node,
                        ),
                        node,
                    ),
                )

append(
                statements,
                setOriginalNode(
                    setTextRange(
                        factory.createFunctionDeclaration(
                            visitNodes(node.modifiers, modifierVisitor, isModifier),
                            node.asteriskToken,
                            factory.getDeclarationName(node, /*allowComments*/ true, /*allowSourceMaps*/ true),
                            /*typeParameters*/ undefined,
                            visitNodes(node.parameters, visitor, isParameter),
                            /*type*/ undefined,
                            visitEachChild(node.body, visitor, context),
                        ),
                        /*location*/ node,
                    ),
                    /*original*/ node,
                ),
            )

append(
                statements,
                setOriginalNode(
                    setTextRange(
                        factory.createClassDeclaration(
                            visitNodes(node.modifiers, modifierVisitor, isModifierLike),
                            factory.getDeclarationName(node, /*allowComments*/ true, /*allowSourceMaps*/ true),
                            /*typeParameters*/ undefined,
                            visitNodes(node.heritageClauses, visitor, isHeritageClause),
                            visitNodes(node.members, visitor, isClassElement),
                        ),
                        node,
                    ),
                    node,
                ),
            )

append(
                hoistedStatements,
                factory.updateFunctionDeclaration(
                    node,
                    visitNodes(node.modifiers, modifierVisitor, isModifierLike),
                    node.asteriskToken,
                    factory.getDeclarationName(node, /*allowComments*/ true, /*allowSourceMaps*/ true),
                    /*typeParameters*/ undefined,
                    visitNodes(node.parameters, visitor, isParameter),
                    /*type*/ undefined,
                    visitNode(node.body, visitor, isBlock),
                ),
            )

append(
            statements,
            setTextRange(
                factory.createExpressionStatement(
                    factory.createAssignment(
                        name,
                        setTextRange(
                            factory.createClassExpression(
                                visitNodes(node.modifiers, modifierVisitor, isModifierLike),
                                node.name,
                                /*typeParameters*/ undefined,
                                visitNodes(node.heritageClauses, visitor, isHeritageClause),
                                visitNodes(node.members, visitor, isClassElement),
                            ),
                            node,
                        ),
                    ),
                ),
                node,
            ),
        )
